idth: 22px;\n      height: 22px;\n      padding: 0;\n      font-size: 11px;\n      line-height: 20px;\n      font-family: inherit;\n      background: transparent;\n      color: var(--muted);\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-ctl);\n      cursor: pointer;\n      margin-left: auto;\n      transition: color 0.12s ease, background 0.12s ease, transform 0.08s ease;\n    }\n\n    .sidebar-close:hover {\n      color: var(--text);\n      background: var(--hover-wash);\n    }\n\n    .sidebar-close:active {\n      transform: scale(0.95);\n    }\n\n    .tree-container {\n      flex: 1;\n      overflow: auto;\n      padding: 6px 0;\n    }\n\n    .tree-node {\n      padding: 4px 16px;\n      cursor: pointer;\n      display: flex;\n      align-items: baseline;\n      font-size: 11px;\n      line-height: 15px;\n      white-space: nowrap;\n    }\n\n    .tree-node:hover {\n      background: var(--hover-wash);\n    }\n\n    .tree-node.active {\n      background: var(--selectedBg);\n      box-shadow: inset 2px 0 0 var(--accent);\n    }\n\n    .tree-node.active .tree-content {\n      font-weight: bold;\n    }\n\n    .tree-node.in-path {\n      background: color-mix(in srgb, var(--accent) 8%, transparent);\n    }\n\n    .tree-node.in-path.active {\n      background: var(--selectedBg);\n    }\n\n    .tree-prefix {\n      color: var(--dim);\n      flex-shrink: 0;\n      font-family: var(--font-mono);\n      white-space: pre;\n    }\n\n    .tree-marker {\n      color: var(--accent);\n      flex-shrink: 0;\n    }\n\n    .tree-content {\n      color: var(--text);\n    }\n\n    .tree-label {\n      color: color-mix(in srgb, var(--accent) 80%, var(--text));\n    }\n\n    .tree-role-user {\n      color: var(--accent);\n    }\n\n    .tree-role-developer {\n      color: var(--dim);\n    }\n\n    .tree-role-assistant {\n      color: var(--success);\n    }\n\n    .tree-role-tool {\n      color: var(--muted);\n    }\n\n    .tree-muted {\n      color: var(--muted);\n    }\n\n    .tree-error {\n      color: var(--error);\n    }\n\n    .tree-compaction {\n      color: var(--borderAccent);\n    }\n\n    .tree-branch-summary {\n      color: var(--warning);\n    }\n\n    .tree-custom-message {\n      color: var(--customMessageLabel);\n    }\n\n    .tree-status {\n      padding: 5px 12px;\n      font-size: 10px;\n      color: var(--muted);\n      flex-shrink: 0;\n      border-top: 1px solid var(--hairline-soft);\n    }\n\n    #sidebar-resizer {\n      width: var(--sidebar-resizer-width);\n      flex-shrink: 0;\n      height: 100%;\n      cursor: col-resize;\n      touch-action: none;\n      background: transparent;\n      transition: background 0.12s ease;\n    }\n\n    #sidebar-resizer:hover,\n    body.sidebar-resizing #sidebar-resizer {\n      background: color-mix(in srgb, var(--accent) 25%, transparent);\n    }\n\n    /* ================= Main content ================= */\n\n    #workspace {\n      flex: 1;\n      min-width: 0;\n      display: flex;\n      flex-direction: column;\n      overflow: hidden;\n      border: 1px solid var(--hairline);\n      border-radius: 16px;\n      background: var(--container-bg);\n    }\n\n    #content {\n      flex: 1;\n      min-height: 0;\n      overflow: auto;\n      padding: 28px 32px 48px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      overscroll-behavior: contain;\n    }\n\n    #trace-panel { flex: none; min-height: 0; border-top: 1px solid var(--hairline); background: var(--container-bg); }\n    .trace-panel-bar { min-height: 42px; display: flex; align-items: center; gap: 12px; padding: 6px 16px; }\n    #timeline-toggle { display: flex; align-items: center; gap: 10px; border: 0; background: transparent; color: var(--text); font-size: 12px; flex: 1; min-width: 0; text-align: left; }\n    #timeline-toggle:disabled { cursor: default; }\n    #timeline-toggle:hover:not(:disabled), .chrome-button:hover { color: var(--accent); }\n    .timeline-chevron { color: var(--muted); font-size: 16px; }\n    #timeline-toggle[aria-expanded=\"true\"] .timeline-chevron { transform: rotate(180deg); }\n    #trace-summary { color: var(--dim); font-size: 11px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n    .chrome-button { color: var(--muted); background: transparent; border: 1px solid var(--hairline); padding: 3px 9px; border-radius: 6px; font-size: 11px; }\n    #trace-body { height: clamp(240px, 42dvh, 480px); overflow: auto; overscroll-behavior: contain; padding: 8px 16px 16px; }\n    oms-session-trace { display: block; }\n    .trace-view #trace-panel { display: flex; flex-direction: column; flex: 1; border-top: 0; }\n    .trace-view #trace-body { flex: 1; height: auto; }\n    .trace-view .timeline-chevron { display: none; }\n\n    #content > * {\n      flex-shrink: 0;\n      width: 100%;\n      max-width: var(--content-max-width);\n    }\n\n    /* ================= Header card ================= */\n\n    .header {\n      padding: 0 0 24px;\n      margin-bottom: 24px;\n      border-bottom: 1px solid var(--hairline);\n    }\n\n    .session-eyebrow { color: var(--accent); font-size: 10px; text-transform: uppercase; letter-spacing: .09em; margin-bottom: 8px; overflow-wrap: anywhere; }\n    .empty-session { padding: 36px 0; color: var(--muted); text-align: center; }\n\n    .header h1 {\n      font-size: 24px;\n      line-height: 1.3;\n      font-weight: 600;\n      letter-spacing: -0.035em;\n      color: var(--text);\n      margin-bottom: 2px;\n      overflow-wrap: anywhere;\n    }\n\n    .help-bar {\n      font-size: 11px;\n      color: var(--dim);\n      margin: 8px 0 20px;\n    }\n\n    .header-info {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 18px 24px;\n      font-size: 12px;\n    }\n\n    .info-item {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n      min-width: 0;\n    }\n\n    .info-label {\n      font-size: 9.5px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--dim);\n    }\n\n    .info-value {\n      color: var(--text);\n      overflow-wrap: anywhere;\n      font-variant-numeric: tabular-nums;\n    }\n\n    /* ================= System prompt / tools panels ================= */\n\n    .system-prompt {\n      background: color-mix(in srgb, var(--container-bg) 45%, var(--body-bg));\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-card);\n      padding: 10px 14px;\n      margin-bottom: 14px;\n    }\n\n    .system-prompt-header {\n      font-size: 10px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--customMessageLabel, var(--muted));\n    }\n\n    .system-prompt-content {\n      color: var(--customMessageText, var(--muted));\n      white-space: pre-wrap;\n      word-wrap: break-word;\n      font-size: 11px;\n      max-height: 240px;\n      overflow-y: auto;\n      overscroll-behavior: contain;\n      margin-top: 8px;\n      padding: 8px 10px;\n      background: var(--inset-bg);\n      border-radius: var(--radius-ctl);\n    }\n\n    .system-prompt.provider-prompt {\n      border-left: 2px solid var(--warning);\n    }\n\n    .system-prompt-note {\n      font-size: 10px;\n      font-style: italic;\n      color: var(--muted);\n      margin-top: 6px;\n    }\n\n    .tools-list {\n      background: color-mix(in srgb, var(--container-bg) 45%, var(--body-bg));\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-card);\n      padding: 10px 14px;\n      margin-bottom: 14px;\n      cursor: pointer;\n    }\n\n    .tools-header {\n      font-size: 10px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--warning);\n      margin-bottom: 8px;\n    }\n\n    .tools-list.collapsed .tools-header {\n      margin-bottom: 0;\n    }\n\n    .tools-list.collapsed .tools-content {\n      display: none;\n    }\n\n    .tools-list:not(.collapsed) .tools-collapsed {\n      display: none;\n    }\n\n    .tools-collapsed {\n      margin-top: 6px;\n      display: flex;\n      flex-wrap: wrap;\n      gap: 4px;\n    }\n\n    .tools-content {\n      display: flex;\n      flex-direction: column;\n      gap: 3px;\n      max-height: 320px;\n      overflow-y: auto;\n      overscroll-behavior: contain;\n    }\n\n    .tool-name-chip {\n      display: inline-block;\n      padding: 0 6px;\n      border-radius: 3px;\n      background: color-mix(in srgb, var(--text) 6%, transparent);\n      color: var(--muted);\n      font-size: 10px;\n      line-height: 17px;\n      font-weight: 500;\n    }\n\n    .tool-item {\n      font-size: 11px;\n    }\n\n    .tool-item-name {\n      font-weight: 600;\n      color: var(--text);\n    }\n\n    .tool-item-desc {\n      color: var(--dim);\n    }\n\n    /* ================= Messages ================= */\n\n    #messages {\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n    }\n\n    .message-timestamp {\n      font-size: 10px;\n      color: var(--dim);\n    }\n\n    .user-message,\n    .assistant-message {\n      position: relative;\n      border-radius: var(--radius-card);\n    }\n\n    .user-message > .message-timestamp,\n    .assistant-message > .message-timestamp {\n      position: absolute;\n      top: 9px;\n      right: 40px;\n      line-height: 14px;\n    }\n\n    .user-message::before,\n    .assistant-message::before {\n      display: block;\n      font-size: 9.5px;\n      font-weight: 600;\n      letter-spacing: 0.08em;\n      text-transform: uppercase;\n      line-height: 14px;\n      margin-bottom: 6px;\n    }\n\n    .user-message {\n      background: color-mix(in srgb, var(--accent) 6%, transparent);\n      border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--hairline));\n      color: var(--userMessageText, var(--text));\n      padding: 9px 14px 11px;\n    }\n\n    .user-message::before {\n      content: 'user';\n      color: color-mix(in srgb, var(--accent) 85%, var(--text));\n    }\n\n    .user-message.developer-message {\n      background: color-mix(in srgb, var(--text) 3%, transparent);\n      border-color: var(--hairline);\n    }\n\n    .user-message.developer-message::before {\n      content: 'developer';\n      color: var(--dim);\n    }\n\n    .user-message.developer-message .markdown-content {\n      color: var(--dim);\n    }\n\n    .assistant-message {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n      padding: 0 1px;\n    }\n\n    .assistant-message::before {\n      content: 'assistant';\n      color: color-mix(in srgb, var(--success) 80%, var(--text));\n      margin-bottom: -2px;\n    }\n\n    .assistant-text {\n      padding: 0;\n      color: var(--assistantMessageText, var(--text));\n    }\n\n    /* Copy link button - appears on hover */\n    .copy-link-btn {\n      position: absolute;\n      top: 5px;\n      right: 6px;\n      width: 24px;\n      height: 24px;\n      padding: 5px;\n      background: color-mix(in srgb, var(--body-bg) 70%, transparent);\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-ctl);\n      color: var(--muted);\n      cursor: pointer;\n      opacity: 0;\n      transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease, transform 0.08s ease;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      z-index: 10;\n    }\n\n    .copy-link-btn svg {\n      width: 12px;\n      height: 12px;\n    }\n\n    .user-message:hover .copy-link-btn,\n    .assistant-message:hover .copy-link-btn,\n    .copy-link-btn:focus-visible {\n      opacity: 1;\n    }\n\n    .copy-link-btn:hover {\n      background: var(--hover-wash);\n      color: var(--text);\n      border-color: var(--hairline-strong);\n    }\n\n    .copy-link-btn:active {\n      transform: scale(0.92);\n    }\n\n    .copy-link-btn.copied {\n      opacity: 1;\n      background: color-mix(in srgb, var(--success) 15%, transparent);\n      color: var(--success);\n      border-color: color-mix(in srgb, var(--success) 45%, transparent);\n    }\n\n    /* Highlight effect for deep-linked messages */\n    .user-message.highlight,\n    .assistant-message.highlight {\n      animation: highlight-pulse 2s ease-out;\n    }\n\n    @keyframes highlight-pulse {\n      0% {\n        box-shadow: 0 0 0 3px var(--accent);\n      }\n      100% {\n        box-shadow: 0 0 0 0 transparent;\n      }\n    }\n\n    /* ================= Thinking blocks ================= */\n\n    .thinking-block {\n      border-left: 2px solid var(--hairline-strong);\n      padding: 1px 0 1px 12px;\n    }\n\n    .thinking-text {\n      display: none;\n      color: var(--thinkingText, var(--muted));\n      font-style: italic;\n      font-size: 11.5px;\n      white-space: pre-wrap;\n    }\n\n    .thinking-collapsed {\n      display: block;\n      color: var(--dim);\n      font-style: italic;\n      font-size: 11px;\n    }\n\n    /* ================= Tool executions (bash / js) ================= */\n\n    .tool-execution {\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-ctl);\n      padding: 8px 12px;\n      font-size: 11.5px;\n      overflow: hidden;\n    }\n\n    .tool-execution.error {\n      border-color: color-mix(in srgb, var(--error) 40%, var(--hairline));\n    }\n\n    .tool-execution.pending {\n      border-style: dashed;\n    }\n\n    .tool-execution > .message-timestamp {\n      float: right;\n      margin-left: 10px;\n    }\n\n    /* Tool calls render inside the <oms-tool-view> web component, which draws\n       its own card chrome; the host box collapses to a plain block. */\n    oms-tool-view.tool-execution {\n      display: block;\n      padding: 0;\n      background: none;\n      border: none;\n      border-radius: 0;\n      overflow: visible;\n    }\n\n    .tool-command {\n      font-weight: 600;\n      white-space: pre-wrap;\n      word-wrap: break-word;\n      overflow-wrap: break-word;\n      word-break: break-word;\n      padding-left: 13px;\n      position: relative;\n    }\n\n    .tool-command::before {\n      content: '';\n      position: absolute;\n      left: 0;\n      top: 5px;\n      width: 7px;\n      height: 7px;\n      border-radius: 50%;\n      background: var(--dim);\n    }\n\n    .tool-execution.success > .tool-command::before {\n      background: var(--success);\n    }\n\n    .tool-execution.error > .tool-command::before {\n      background: var(--error);\n    }\n\n    .tool-output {\n      margin-top: 8px;\n      padding: 7px 9px;\n      border-radius: 4px;\n      background: var(--inset-bg);\n      color: var(--toolOutput, var(--muted));\n      word-wrap: break-word;\n      overflow-wrap: break-word;\n      word-break: break-word;\n      font-family: inherit;\n      font-size: 11.5px;\n      overflow-x: auto;\n    }\n\n    .tool-output > div,\n    .output-preview,\n    .output-full {\n      margin: 0;\n      padding: 0;\n      line-height: var(--line-height);\n    }\n\n    .tool-output pre {\n      margin: 0;\n      padding: 0;\n      font-family: inherit;\n      color: inherit;\n      white-space: pre-wrap;\n      word-wrap: break-word;\n      overflow-wrap: break-word;\n    }\n\n    .tool-output code {\n      padding: 0;\n      background: none;\n      color: var(--text);\n    }\n\n    .tool-output.expandable {\n      cursor: pointer;\n    }\n\n    .tool-output.expandable:hover .expand-hint {\n      color: var(--text);\n      text-decoration: underline;\n    }\n\n    .tool-output.expandable .output-full {\n      display: none;\n    }\n\n    .tool-output.expandable.expanded .output-preview {\n      display: none;\n    }\n\n    .tool-output.expandable.expanded .output-full {\n      display: block;\n    }\n\n    .expand-hint {\n      color: var(--dim);\n      font-size: 10.5px;\n    }\n\n    /* ================= Meta entries ================= */\n\n    .model-change,\n    .thinking-change {\n      padding: 0 2px;\n      color: var(--dim);\n      font-size: 11px;\n    }\n\n    .model-name,\n    .thinking-level {\n      color: var(--borderAccent, var(--accent));\n      font-weight: 600;\n    }\n\n    /* Compaction / Branch Summary - matches customMessage colors from TUI */\n    .compaction {\n      background: color-mix(in srgb, var(--customMessageBg, var(--container-bg)) 70%, var(--body-bg));\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-card);\n      padding: 9px 14px;\n      cursor: pointer;\n    }\n\n    .compaction-label {\n      font-size: 10px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--customMessageLabel, var(--muted));\n      margin-bottom: 2px;\n    }\n\n    .compaction-collapsed {\n      color: var(--customMessageText, var(--muted));\n      font-size: 11px;\n    }\n\n    .compaction-content {\n      display: none;\n      color: var(--customMessageText, var(--muted));\n      white-space: pre-wrap;\n      margin-top: 8px;\n      font-size: 11.5px;\n    }\n\n    .compaction.expanded .compaction-collapsed {\n      display: none;\n    }\n\n    .compaction.expanded .compaction-content {\n      display: block;\n    }\n\n    .branch-summary {\n      background: color-mix(in srgb, var(--customMessageBg, var(--container-bg)) 70%, var(--body-bg));\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-card);\n      padding: 9px 14px;\n    }\n\n    .branch-summary-header {\n      font-size: 10px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--borderAccent, var(--accent));\n      margin-bottom: 4px;\n    }\n\n    /* Hook/custom messages */\n    .hook-message {\n      background: color-mix(in srgb, var(--customMessageBg, var(--container-bg)) 70%, var(--body-bg));\n      border: 1px solid var(--hairline);\n      border-radius: var(--radius-card);\n      color: var(--customMessageText, var(--muted));\n      padding: 9px 14px;\n    }\n\n    .hook-type {\n      font-size: 10px;\n      font-weight: 600;\n      letter-spacing: 0.06em;\n      text-transform: uppercase;\n      color: var(--customMessageLabel, var(--muted));\n      margin-bottom: 2px;\n    }\n\n    /* Error */\n    .error-text {\n      color: var(--error);\n      padding: 0 2px;\n    }\n\n    /* Share viewer fetch/decrypt failure (template.js showLoadError) */\n    .share-load-error {\n      margin: 36px auto;\n      max-width: 640px;\n      padding: 14px 16px;\n      background: color-mix(in srgb, var(--error) 7%, transparent);\n      border: 1px solid color-mix(in srgb, var(--error) 40%, transparent);\n      border-radius: var(--radius-card);\n      color: var(--error);\n    }\n\n    /* Images */\n    .message-images {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 8px;\n      margin-bottom: 10px;\n    }\n\n    .message-image {\n      max-width: 100%;\n      max-height: 400px;\n      border-radius: var(--radius-ctl);\n      border: 1px solid var(--hairline);\n      margin: 0;\n    }\n\n    /* ================= Markdown content ================= */\n\n    .markdown-content {\n      overflow-wrap: anywhere;\n    }\n\n    .markdown-content h1,\n    .markdown-content h2,\n    .markdown-content h3,\n    .markdown-content h4,\n    .markdown-content h5,\n    .markdown-content h6 {\n      color: var(--mdHeading, var(--text));\n      margin: var(--line-height) 0 4px 0;\n      font-weight: 650;\n      line-height: 1.4;\n    }\n\n    .markdown-content h1:first-child,\n    .markdown-content h2:first-child,\n    .markdown-content h3:first-child {\n      margin-top: 0;\n    }\n\n    .markdown-content h1 { font-size: 1.25em; }\n    .markdown-content h2 { font-size: 1.15em; }\n    .markdown-content h3 { font-size: 1.05em; }\n    .markdown-content h4 { font-size: 1em; }\n    .markdown-content h5 { font-size: 1em; }\n    .markdown-content h6 { font-size: 1em; letter-spacin